import type { ChainedCommands, Editor } from "@tiptap/core";

export type ControlOperation =
  | ((editor: Editor) => void)
  | { name: string; attributes?: Record<string, unknown> | string };

export const chainFocus = (editor: Editor): ChainedCommands =>
  editor.chain().focus();

export const runOperation = (
  editor: Editor,
  operation: ControlOperation
): void => {
  if (typeof operation === "function") {
    operation(editor);
    return;
  }
  const commands = editor.chain().focus() as unknown as Record<
    string,
    (attributes?: unknown) => { run: () => boolean }
  >;
  commands[operation.name]?.(operation.attributes).run();
};

import type { Editor } from "@tiptap/core";
import { Button } from "@components/custom-controls/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@components/custom-controls/ui/dialog";
import type { ReactNode } from "react";
import { memo, useCallback, useState } from "react";

import { useEditorControls, useResolvedEditor } from "./context";
import { nodeActive, extensionPresent } from "./detection";
import { shallowEqual, useEditorState } from "./editor-state";
import type { ControlsLabels } from "./labels";

export interface CreateContentControlOptions {
  dialog?: (editor: Editor, close: () => void) => ReactNode;
  dialogDescription?: string;
  dialogTitle?: string;
  extensionName: string;
  icon: ReactNode;
  label: keyof ControlsLabels | string;
  nodeName?: string;
  run?: (editor: Editor) => void;
}

export interface ContentControlProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

export const createContentControl = (options: CreateContentControlOptions) => {
  const Control = memo(
    ({
      className,
      editor: editorProp,
      size = "icon-sm",
    }: ContentControlProps) => {
      const { labels } = useEditorControls();
      const editor = useResolvedEditor(editorProp);
      const [open, setOpen] = useState(false);

      const editorState =
        useEditorState(
          editor,
          (edit) => ({
            active: options.nodeName ? nodeActive(edit, options.nodeName) : false,
            disabled: !extensionPresent(edit, options.extensionName),
          }),
          shallowEqual
        ) ?? { active: false, disabled: true };

      const label =
        labels[options.label as keyof ControlsLabels] ?? options.label;

      const close = useCallback(() => setOpen(false), []);

      const run = useCallback(() => {
        if (!editor || editor.isDestroyed || editorState.disabled) {
          return;
        }
        options.run?.(editor);
      }, [editor, editorState.disabled]);

      if (!options.dialog) {
        return (
          <Button
            aria-label={label}
            className={className}
            data-active={editorState.active ? "true" : undefined}
            disabled={editorState.disabled}
            size={size}
            title={label}
            variant="ghost"
            onClick={run}
          >
            {options.icon}
          </Button>
        );
      }

      return (
        <Dialog open={open} onOpenChange={setOpen}>
          <DialogTrigger
            disabled={editorState.disabled}
            render={
              <Button
                aria-label={label}
                className={className}
                disabled={editorState.disabled}
                size={size}
                title={label}
                variant="ghost"
              />
            }
          >
            {options.icon}
          </DialogTrigger>
          <DialogContent>
            <DialogHeader>
              <DialogTitle>{options.dialogTitle ?? label}</DialogTitle>
              {options.dialogDescription ? (
                <DialogDescription>{options.dialogDescription}</DialogDescription>
              ) : null}
            </DialogHeader>
            {editor ? options.dialog(editor, close) : null}
          </DialogContent>
        </Dialog>
      );
    }
  );
  Control.displayName = `createContentControl(${options.label})`;
  return Control;
};

import type { Editor } from "@tiptap/core";
import type { ReactNode } from "react";
import { createContext, useContext, useMemo } from "react";

import type { ControlsLabels } from "./labels";
import { DEFAULT_CONTROLS_LABELS } from "./labels";

export interface EditorControlsContextValue {
  editor: Editor | null;
  labels: ControlsLabels;
}

const EditorControlsContext = createContext<EditorControlsContextValue>({
  editor: null,
  labels: DEFAULT_CONTROLS_LABELS,
});

export interface EditorControlsProviderProps {
  children: ReactNode;
  editor?: Editor | null;
  labels?: Partial<ControlsLabels>;
}

export const EditorControlsProvider = ({
  children,
  editor = null,
  labels,
}: EditorControlsProviderProps) => {
  const value = useMemo(
    () => ({
      editor,
      labels: { ...DEFAULT_CONTROLS_LABELS, ...labels },
    }),
    [editor, labels]
  );

  return (
    <EditorControlsContext.Provider value={value}>
      {children}
    </EditorControlsContext.Provider>
  );
};

export const useEditorControls = (): EditorControlsContextValue =>
  useContext(EditorControlsContext);

export const useResolvedEditor = (
  editor: Editor | null | undefined
): Editor | null => {
  const context = useContext(EditorControlsContext);
  return editor ?? context.editor ?? null;
};

import type { Editor } from "@tiptap/core";
import { Button } from "@components/custom-controls/ui/button";
import type { ReactNode } from "react";
import { memo } from "react";

import { runOperation } from "./commands";
import type { ControlOperation } from "./commands";
import { useEditorControls, useResolvedEditor } from "./context";
import { shallowEqual, useEditorState } from "./editor-state";
import type { ControlsLabels } from "./labels";

export interface CreateControlOptions {
  icon: ReactNode;
  isActive?: (editor: Editor) => boolean;
  isDisabled?: (editor: Editor) => boolean;
  label: keyof ControlsLabels | string;
  operation: ControlOperation;
}

export interface ControlProps {
  className?: string;
  editor?: Editor | null;
  size?: "icon" | "icon-lg" | "icon-sm";
}

export const createControl = (options: CreateControlOptions) => {
  const Control = memo(
    ({ className, editor: editorProp, size = "icon-sm" }: ControlProps) => {
      const { labels } = useEditorControls();
      const editor = useResolvedEditor(editorProp);

      const editorState =
        useEditorState(
          editor,
          (edit) => ({
            active: options.isActive?.(edit) ?? false,
            disabled: options.isDisabled?.(edit) ?? false,
          }),
          shallowEqual
        ) ?? { active: false, disabled: true };

      const label =
        labels[options.label as keyof ControlsLabels] ?? options.label;

      return (
        <Button
          aria-label={label}
          aria-pressed={editorState.active}
          className={className}
          data-active={editorState.active ? "true" : undefined}
          disabled={editorState.disabled}
          size={size}
          title={label}
          variant="ghost"
          onClick={() => {
            if (editor && !editor.isDestroyed && !editorState.disabled) {
              runOperation(editor, options.operation);
            }
          }}
        >
          {options.icon}
        </Button>
      );
    }
  );
  Control.displayName = `createControl(${options.label})`;
  return Control;
};

import type { Editor } from "@tiptap/core";

export const extensionPresent = (
  editor: Editor | null,
  name: string
): boolean =>
  Boolean(
    editor &&
      !editor.isDestroyed &&
      editor.extensionManager.extensions.some((extension) => extension.name === name)
  );

export const nodeActive = (
  editor: Editor | null,
  name: string,
  attributes?: Record<string, unknown>
): boolean =>
  Boolean(
    editor && !editor.isDestroyed && editor.isActive(name, attributes)
  );

import type { Editor } from "@tiptap/core";
import { useCallback, useEffect, useRef, useSyncExternalStore } from "react";

const defaultEqual = <T>(a: T, b: T): boolean => a === b;

export const shallowEqual = <T extends Record<string, unknown>>(
  a: T,
  b: T
): boolean => {
  if (a === b) {
    return true;
  }
  if (!a || !b) {
    return false;
  }
  const ak = Object.keys(a);
  const bk = Object.keys(b);
  if (ak.length !== bk.length) {
    return false;
  }
  return ak.every((k) => a[k] === b[k]);
};

export const useEditorState = <T>(
  editor: Editor | null,
  selector: (e: Editor) => T,
  isEqual: (a: T, b: T) => boolean = defaultEqual
): T | undefined => {
  const selectorRef = useRef(selector);
  const isEqualRef = useRef(isEqual);

  useEffect(() => {
    selectorRef.current = selector;
    isEqualRef.current = isEqual;
  });

  const snapshotRef = useRef<{ value: T | undefined }>({
    value: editor ? selector(editor) : undefined,
  });

  const updateSnapshot = useCallback(() => {
    if (!editor) {
      return;
    }
    const next = selectorRef.current(editor);
    const current = snapshotRef.current.value;
    if (current !== undefined && isEqualRef.current(current, next)) {
      return;
    }
    snapshotRef.current = { value: next };
  }, [editor]);

  const subscribe = useCallback(
    (onStoreChange: () => void) => {
      if (!editor) {
        return () => undefined;
      }
      const update = () => {
        updateSnapshot();
        onStoreChange();
      };
      editor.on("selectionUpdate", update);
      editor.on("transaction", update);
      return () => {
        editor.off("selectionUpdate", update);
        editor.off("transaction", update);
      };
    },
    [editor, updateSnapshot]
  );

  const getSnapshot = useCallback(
    (): T | undefined => snapshotRef.current.value,
    []
  );

  return useSyncExternalStore(subscribe, getSnapshot, getSnapshot);
};

